  function field(label,control,hint=''){return '<label class="tbi-field"><span>'+label+'</span>'+control+(hint?'<small>'+e(hint)+'</small>':'')+'</label>';}
  function scopeKey(){try{const c=root.parent?.DSession?.context?.(),native=root.DNativeContext?.context;if(c)return JSON.stringify([c.account?.id,c.scope?.id,c.scope?.kind,native?.account?.id,native?.scope?.id]);const a=root.AppState?.effectiveAccess?.()||root.AppState?.get?.()||{};return JSON.stringify([a.accountId,a.tenantId,a.enterpriseId,a.valid]);}catch(_){return '';}}
  function specOf(spec){if(!spec||!['AI','PREDICTIVE'].includes(spec.method)||spec.taskId===undefined||spec.taskId===null||!String(spec.taskId).trim())throw Error('请从准确的AI或预外呼任务打开导入。');const importChannel=spec.importChannel===undefined?'MANUAL':spec.importChannel;if(!['MANUAL','API'].includes(importChannel))throw Error('任务导入渠道须为手工或接口。');return {method:spec.method,taskId:String(spec.taskId),importChannel,...(spec.aiSceneId?{aiSceneId:String(spec.aiSceneId)}:{}),...(spec.categoryId?{categoryId:String(spec.categoryId)}:{})};}
