  function options(items,selected,idKey='id',nameKey='name',placeholder='请选择'){return '<option value="">'+e(placeholder)+'</option>'+(items||[]).map(item=>{const id=String(item[idKey]??item.id??item.categoryId??item.sceneId??'');return '<option value="'+e(id)+'"'+(id===String(selected||'')?' selected':'')+'>'+e(item[nameKey]||item.name||item.label||id)+'</option>';}).join('');}
  function schema(d=current){const source=d?.context?.fields||d?.context?.importSchema||[],rows=source.filter(item=>item&&item.usage!=='FOLLOWUP'&&item.source!=='FOLLOWUP').map(item=>({...item,key:String(item.key||item.fieldId||item.id||''),label:item.label||item.name||item.key||item.id}));if(!rows.some(item=>item.key==='code'))rows.unshift({key:'code',id:'code',label:d?.context?.codeLabel||'业务编码',type:'text',required:true,source:'SYSTEM'});const keys=rows.map(item=>item.key);if(keys.some(key=>!key)||new Set(keys).size!==keys.length)throw Error('当前分类导入字段身份缺失或重复，请先核对分类配置。');return rows;}
  function importLimits(d=current){const raw=d?.context?.importLimits||{},maxRows=Number(raw.maxRows??2000),maxBytes=Number(raw.maxBytes??(d?.spec.method==='AI'?16777216:1048576));if(!Number.isSafeInteger(maxRows)||maxRows<1||maxRows>150000||!Number.isSafeInteger(maxBytes)||maxBytes<1||maxBytes>16777216)throw Error('当前任务导入容量未能准确读取，请刷新配置。');return {maxRows,maxBytes};}
  function stampSchema(d){return JSON.stringify(schema(d));}
  function capture(d=current){if(!d||!alive(d))return;for(const [key,id] of [['name','tbi-name'],['text','tbi-text'],['priority','tbi-priority']]){const node=root.document.getElementById(id);if(node)d[key]=key==='priority'?Number(node.value):node.value;}}
  function showMessage(message,tone='error'){const d=current;if(!alive(d))return;d.message=message||'';d.messageTone=tone;const host=root.document.getElementById('tbi-message');if(host){host.className='tbi-message '+tone;host.textContent=message||'';}renderSubmitHint(d);}
  function partialDraftIdentity(d){return JSON.stringify([d.owner,d.spec.method,String(d.spec.taskId),d.spec.importChannel,d.context?.categoryId||d.spec.categoryId,stampSchema(d)]);}
