      d.hostKind='native';root.PlatformUI.openLayer(modalId,html,'large tbi-import-shell',{objectKey:'task-business-import:'+d.sequence,isDirty:()=>!!(current===d&&(d.dirty||d.busy||d.pendingRequestId)),onBackdropClick:()=>close()});d.modal=root.document.getElementById(modalId);return;
