    const api=ready&&!isManual?'<p class="tbi-api-note">当前任务通过接口接收名单，无需上传文件。接收字段沿用已关联配置。</p>'+guide:'';
    const message=d.loading?'<p class="tbi-hint" role="status">正在读取任务配置…</p>':!ready?'<div class="tbi-context-issues">'+e(d.message||(ctx.issues||[]).join('；')||(d.spec.taskId?'当前任务关联配置不完整，请先维护任务配置。':'请选择目标任务。'))+'</div>'+(d.spec.taskId?'<div class="tbi-actions">'+button('维护任务关联','openTaskConfiguration')+button('重新读取','refreshContext')+'</div>':''):'';
    const html='<div class="layer-header"><div><h2 id="tbi-title">导入客户</h2></div><button id="tbi-close" type="button" aria-label="关闭导入" onclick="DTaskBusinessImport.close()">×</button></div><div class="layer-body tbi-import-body">'+selector+context+message+upload+api+'<p id="tbi-message" class="tbi-message '+e(d.messageTone||'error')+'" role="status">'+e(ready?d.message||'':'')+'</p><div id="tbi-close-confirm"></div><p class="tbi-hint" data-import-entry="TASK" data-import-channel="'+e(d.spec.importChannel)+'">名单导入当前任务，按直接跟进处理。</p></div><div class="layer-footer">'+(isManual&&ready?'<p id="tbi-submit-hint" class="tbi-submit-hint" role="status" aria-live="polite"></p>':'')+'<div class="tbi-footer-actions">'+button(d.completed||!isManual?'关闭':'取消','close').replace('<button ','<button id="tbi-footer-close" ')+(isManual&&ready?button('检查名单','preview').replace('<button ','<button id="tbi-check" ')+'<button id="tbi-submit" type="button" class="btn btn-primary" aria-describedby="tbi-submit-hint" onclick="DTaskBusinessImport.submit()">确认导入</button>':'')+'</div></div>';
